                "solution_order": ["Zellige Tile", "Djellaba", "Koutoubia Mosque", "Dromedary"],
                "cultural_insight": "Zellige mosaics reflect Islamic geometric art; djellabas are traditional hooded robes."
            }
        ]
        self.solved_puzzles = set()

    def display_puzzle(self, p_id):
        for p in self.puzzles:
            if p["id"] == p_id:
                print(f"\n🧩 Puzzle: {p['theme']} ({p['culture']})")
                print("Pieces (scrambled):")
                pieces = p["pieces"][:]
                import random
                random.shuffle(pieces)
                for i, piece in enumerate(pieces, 1):
                    print(f"  {i}. {piece.label} ({piece.category})")
                print("\nArrange pieces in logical order (e.g., from nature to culture). Enter indices separated by commas (e.g., 1,2,3,4):")
                return p
        return None

    def submit_solution(self, p_id, indices):
        p = self.display_puzzle(p_id)
        if not p:
            return False
        try:
            selected = [p["pieces"][i - 1].label for i in indices]
            if selected == p["solution_order"]:
                self.solved_puzzles.add(p_id)
                print("✅ Puzzle Solved!")
                print(f"💡 Insight: {p['cultural_insight']}")
                return True
            else:
                print("❌ Incorrect order. Try again!")
                return False
        except (IndexError, ValueError):
            print("⚠️ Invalid input. Please enter numbers separated by commas.")
            return False

    def get_progress(self):
        total = len(self.puzzles)
        solved = len(self.solved_puzzles)
        return f"Puzzle Progress: {solved}/{total} solved"


